void lock_task1(void)
{
    int print_location = 3;
    while (1) {
        int i;
        if (!is_init) {
#ifdef SPIN_LOCK
            spin_lock_init(&spin_lock);
#endif

#ifdef MUTEX_LOCK
            do_mutex_lock_init(&mutex_lock);
#endif
            is_init = TRUE;
