        vt100_move_cursor(1, print_location);
        printk("%s", blank);

        vt100_move_cursor(1, print_location);
        printk("> [TASK] Applying for a lock.\n");

        do_scheduler();

#ifdef SPIN_LOCK
        spin_lock_acquire(&spin_lock);
#endif

#ifdef MUTEX_LOCK
        do_mutex_lock_acquire(&mutex_lock);
#endif

        for (i = 0; i < 20; i++) {
            vt100_move_cursor(1, print_location);
            printk(
