        printk("%s", blank);

        vt100_move_cursor(1, print_location);
        printk("> [TASK] Has acquired lock and exited.\n");

#ifdef SPIN_LOCK
        spin_lock_release(&spin_lock);
#endif

#ifdef MUTEX_LOCK
        do_mutex_lock_release(&mutex_lock);
#endif
        do_scheduler();
