LIST_HEAD(timer_queue);

uint64_t time_elapsed = 0;
uint32_t time_base = 0;
uint64_t timer_interval = 0;

void timer_create(TimerCallback func, void* parameter, uint64_t tick)
{
    disable_preempt();

    list_add_tail(&current_running[cpu_id]->timer.list, &timer_queue);
    current_running[cpu_id]->timer.timeout_tick = tick;
    current_running[cpu_id]->timer.callback_func = func;
    current_running[cpu_id]->timer.parameter = parameter;

    enable_preempt();
}

/* check all timers. if timeouts, call callback_func and free the timer */
void timer_check()
{
    disable_preempt();

    uint64_t current_tick = get_ticks();
    list_node_t* p = timer_queue.next;

    while(p != &timer_queue){
        timer_t *timer_node = list_entry(p, timer_t, list);
        if(current_tick >= timer_node->timeout_tick){
            (timer_node->callback_func)(timer_node->parameter);
            p = p->next;
            list_del(p->prev);
        }
        else{
            p = p->next;
        } 
    }

    enable_preempt();
}

uint64_t get_ticks()
{
    __asm__ __volatile__(
        "rdtime %0"
        : "=r"(time_elapsed));
    return time_elapsed;
}

uint64_t get_timer()
{
    return get_ticks() / time_base;
}

uint64_t get_time_base()
{
    return time_base;
}

void latency(uint64_t time)
{
    uint64_t begin_time = get_timer();

    while (get_timer() - begin_time < time);
    return;
}

#include <os/futex.h>
#include <os/irq.h>
#include <os/mm.h>
#include <assert.h>
#include <os/smp.h>

futex_bucket_t futex_buckets[FUTEX_BUCKETS];

void init_system_futex()
{
    for (int i = 0; i < FUTEX_BUCKETS; ++i) {
        init_list_head(&futex_buckets[i]);
    }
}

// a simple hash function
static int futex_hash(uint64_t x)
{
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
    x = x ^ (x >> 31);
    return x % FUTEX_BUCKETS;
}

static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
{
    int key = futex_hash((uint64_t)val_addr);
    list_node_t *head = &futex_buckets[key];
    for (list_node_t *p = head->next; p != head; p = p->next) {
        futex_node_t *node = list_entry(p, futex_node_t, list);
        if (node->futex_key == (uint64_t)val_addr) {
            return node;
        }
    }

    if (create) {
        futex_node_t *node = (futex_node_t*) kmalloc(sizeof(futex_node_t));
        node->futex_key = (uint64_t)val_addr;
        init_list_head(&node->block_queue);
        list_add_tail(&node->list, &futex_buckets[key]);
        return node;
    }

    return NULL;
}

void futex_wait(volatile uint64_t *val_addr)
{
    disable_preempt();

    futex_node_t *node = get_node(val_addr, 1);
    assert(node != NULL);
    do_block(&current_running[cpu_id]->list, &node->block_queue);
    scheduler();

    enable_preempt();
}

void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
{
    disable_preempt();
    futex_node_t *node = get_node(val_addr, 0);

    if (node != NULL) {
        for (int i = 0; i < num_wakeup; ++i) {
            if (list_empty(&node->block_queue)) break;

            do_unblock(node->block_queue.next);
        }
    }

    scheduler();
    enable_preempt();
}

#include <os/lock.h>
#include <os/sched.h>
#include <atomic.h>

void spin_lock_init(spin_lock_t *lock)
{
    atomic_swap(UNLOCKED, (ptr_t)(&lock->status));
}
void spin_lock_try_acquire(spin_lock_t *lock)
{
    while(atomic_cmpxchg(UNLOCKED, LOCKED, (ptr_t)(&lock->status)) == LOCKED){
        ;
    }
}
void spin_lock_acquire(spin_lock_t *lock)
{
    spin_lock_try_acquire(lock);
}
void spin_lock_release(spin_lock_t *lock)
{
    atomic_swap(UNLOCKED, (ptr_t)(&lock->status));
}

