static void add_owned_binsem(pcb_t *task, int binsem_id)
{
    if (task->binsem_num < (int)(sizeof(task->binsem_id) / sizeof(task->binsem_id[0]))) {
        task->binsem_id[task->binsem_num++] = binsem_id;
    }
}

static void wake_wait_list(list_head *wait_list)
{
    while (!list_empty(wait_list)) {
        do_unblock(wait_list->next);
    }
}

static void release_owned_binsems(pcb_t *task)
{
    for (int i = 0; i < task->binsem_num; i++) {
        int binsem_id = task->binsem_id[i];
        binsem_nodes[binsem_id].sem++;
        if (binsem_nodes[binsem_id].sem <= 0 &&
            !list_empty(&binsem_nodes[binsem_id].block_queue)) {
            list_node_t *waiter = binsem_nodes[binsem_id].block_queue.next;
            add_owned_binsem(list_entry(waiter, pcb_t, list), binsem_id);
            do_unblock(waiter);
        }
    }

    task->binsem_num = 0;
}

static void remove_sleep_timer(pcb_t *task)
{
    for (list_node_t *node = timer_queue.next; node != &timer_queue;) {
        list_node_t *next = node->next;
        if (list_entry(node, timer_t, list) == &task->timer) {
            list_del(node);
            break;
        }
        node = next;
    }
}

static void init_spawned_pcb(pcb_t *task, task_info_t *task_info, void *arg)
{
    regs_context_t *pt_regs;

    task->kernel_sp = allocPage(1);
    task->user_sp = allocPage(1);
    task->preempt_count = 0;
    task->kernel_stack_base = task->kernel_sp;
    task->user_stack_base = task->user_sp;
    list_add_tail(&task->list, &ready_queue);
    init_list_head(&task->wait_list);
    task->binsem_num = 0;
    task->pid = process_id++;
    task->type = task_info->type;
    task->status = TASK_READY;
    task->priority = task_info->priority;
    task->ready_tick = get_ticks();
    task->mask = current_running[cpu_id]->mask;

    pt_regs = (regs_context_t *)(task->kernel_sp - sizeof(regs_context_t));
    task->kernel_sp = (ptr_t)pt_regs;
    pt_regs->regs[1] = task_info->entry_point;
    pt_regs->regs[2] = task->user_sp;
    pt_regs->regs[3] = (reg_t)__global_pointer$;
    pt_regs->regs[10] = (reg_t)arg;
    if (task->type == USER_PROCESS || task->type == USER_THREAD) {
        pt_regs->sstatus = SR_SPIE;
        pt_regs->sepc = task_info->entry_point;
        pt_regs->sscratch = (reg_t)task;
    } else {
        pt_regs->sstatus = SR_SPP | SR_SPIE;
        pt_regs->sepc = task_info->entry_point;
        pt_regs->sscratch = 0;
    }
}

static void make_zombie(pcb_t *task)
{
    task->status = TASK_ZOMBIE;
    if (task->mode == AUTO_CLEANUP_ON_EXIT) {
        list_add_tail(&task->list, &kernel_pcb[0].wait_list);
    }
}

static void cleanup_running_killed_task(pcb_t *task)
{
    wake_wait_list(&task->wait_list);
    release_owned_binsems(task);
    freePage(task->user_stack_base, 1);
    make_zombie(task);
}

/* 
 * Only modify PCB, current_running, process_id and ready_queue
 * DO NOT STORE OR RESTORE 
 * trick: modify $tp in ret_from_exception to ensure
 * disable_preempt() and enable_preempt() modify the same PCB
 */
void scheduler(void)
{
    pcb_t *task = current_running[cpu_id];
    pcb_t *next_task;
    list_node_t *next_node;

    task->cursor_x = screen_cursor_x[cpu_id];
    task->cursor_y = screen_cursor_y[cpu_id];

    if (task->status == TASK_RUNNING && task != &kernel_pcb[cpu_id]) {
        list_add_tail(&task->list, &ready_queue);
        task->status = TASK_READY;
        task->ready_tick = get_ticks();
    } else if (task->status == TASK_KILLED) {
        cleanup_running_killed_task(task);
    }

    next_node = max_priority_node();
    if (next_node == &kernel_pcb[cpu_id].list) {
        next_task = &kernel_pcb[cpu_id];
    } else {
        next_task = list_entry(next_node, pcb_t, list);
        list_del(&next_task->list);
    }

    next_task->status = TASK_RUNNING;
    next_task->cpu_id = cpu_id;
    current_running[cpu_id] = next_task;
    current_cpu_running = next_task;

    vt100_move_cursor(next_task->cursor_x, next_task->cursor_y);
    screen_cursor_x[cpu_id] = next_task->cursor_x;
    screen_cursor_y[cpu_id] = next_task->cursor_y;
}

pid_t do_spawn(task_info_t *task, void* arg, spawn_mode_t mode)
{
    pcb_t *new_task = NULL;

    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == -1) {
            new_task = &pcb[i];
            break;
        }
    }

    if (new_task == NULL) {
        return -1;
    }

    init_spawned_pcb(new_task, task, arg);
    new_task->mode = mode;

    return new_task->pid;
}

void do_exit()
{
    pcb_t *task = current_running[cpu_id];

    wake_wait_list(&task->wait_list);
    release_owned_binsems(task);
    freePage(task->user_stack_base, 1);
    list_del(&task->list);
    make_zombie(task);
    scheduler();
}

// sleep(seconds)
void do_sleep(uint32_t sleep_time)
{
    // 1. block the current_running
    // 2. create a timer which calls `do_unblock` when timeout
    // 3. reschedule because the current_running is blocked
    do_block(&current_running[cpu_id]->list, &sleep_queue);
    list_node_t* parameter = &current_running[cpu_id]->list;
    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
    scheduler();
}

int do_kill(pid_t pid)
{
    pcb_t *task = find_pcb(pid);

    if (task == NULL) {
        return 0;
    }

    if (task->status == TASK_RUNNING) {
        task->status = TASK_KILLED;
        return 1;
    }

    wake_wait_list(&task->wait_list);
    release_owned_binsems(task);
    freePage(task->user_stack_base, 1);
    list_del(&task->list);
    remove_sleep_timer(task);
    make_zombie(task);
    scheduler();

    return 1;
}

int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, regs_context_t *regs)
{
    pcb_t *task = find_pcb(pid);

    if (task == NULL) {
        return 0;
    }

    task->mode = ENTER_ZOMBIE_ON_EXIT;
    if (task->status == TASK_ZOMBIE) {
        if (task->list.prev != NULL && task->list.next != NULL) {
            list_del(&task->list);
        }
        task->status = TASK_EXITED;
        task->pid = -1;
        freePage(task->kernel_stack_base, 1);
        return 1;
    }

    regs->sepc -= 4;
    do_block(&current_running[cpu_id]->list, &task->wait_list);
    scheduler();

    return pid;
}

