int do_taskset(pid_t pid, unsigned long mask)
{
    // search the pcb
    pcb_t *set_pcb = NULL;
    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == pid){
            set_pcb = &pcb[i];
            break;
        }
    }
    if(set_pcb == NULL){
        return 0;
    }

    set_pcb->mask = mask;
    return 1;
}

// block the pcb task into the block queue
void do_block(list_node_t *pcb_node, list_head *queue)
{
    list_del(pcb_node);
    list_add_tail(pcb_node, queue);
    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
}

// unblock the `pcb` from the block queue
void do_unblock(list_node_t *pcb_node)
{
    list_del(pcb_node);
    list_add_tail(pcb_node, &ready_queue);
    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
}

list_node_t* max_priority_node(void)
{
    uint64_t current_tick = get_ticks();
    list_node_t *best = NULL;
    int best_priority = 0x7fffffff;

    for (list_node_t *node = ready_queue.next; node != &ready_queue;
         node = node->next) {
        pcb_t *task = list_entry(node, pcb_t, list);
        int matches_cpu = 0;

        if (cpu_id == 0 && (task->mask & 1ul)) {
            matches_cpu = 1;
        } else if (cpu_id == 1 && (task->mask & 2ul)) {
            matches_cpu = 1;
        }

        if (!matches_cpu) {
            continue;
        }

        int dynamic_priority = task->priority -
            (current_tick - task->ready_tick) / timer_interval;
        if (dynamic_priority < best_priority) {
            best = node;
            best_priority = dynamic_priority;
        }
    }

    if (best == NULL) {
        return &kernel_pcb[cpu_id].list;
    }

    return best;
}

