        }      
        else if(exec_command){
            if(argc <= 1){
                check_print_location();
                printf("Too few arguments for command exec!\n");
                print_location_y++;
                continue;
            }

            char* _argv[MAX_ARGC - 1];
            for(int i = 0; i < MAX_ARGC - 1; i++){
