int do_link(char* filename, char* newfile, int mode)
{
    /* Search Parent Dir */
    enable_sum();

    int filename_pos = 0;
    dir_t* cur_dir;
    uint16_t lastdir_inode;
    uint32_t lastdir_block;

    // search from root dir / current dir?
    if(filename[filename_pos] == '/'){
        read_superblock();
        read_block(superblock->root_block_id);
        cur_dir = cached_block_base;
        lastdir_inode = superblock->root_inode_id;
        lastdir_block = superblock->root_block_id;
        filename_pos++;    
    }
    else{
        read_block(current_dir_block);
        cur_dir = cached_block_base;
        lastdir_inode = current_dir_inode;
        lastdir_block = current_dir_block;
    }

    char nextdirname[29];
    while(1){
        // Get name of next dir
        int nextdirname_pos = 0;
        while(filename[filename_pos] != '/' && filename[filename_pos] != '\0'){
            nextdirname[nextdirname_pos++] = filename[filename_pos++];
        }
        nextdirname[nextdirname_pos] = '\0';

        // Last?
        if(filename[filename_pos] == '\0'){
            break;
        }

        // Search
        int i = 0;
        uint16_t nextdir_inode_id;
        uint32_t nextdir_block_id;
        for(i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == DIR && !strcmp(cur_dir->entry[i].name, nextdirname)){
                nextdir_inode_id = cur_dir->entry[i].inode;
                inode_t* nextdir_inode = read_inode(nextdir_inode_id);
                nextdir_block_id = nextdir_inode->direct_blocks[0];
                lastdir_inode = nextdir_inode_id;
                lastdir_block = nextdir_block_id;
                break;
            }
        }
        if(i == 128){
            disable_sum();
            return 0;
        }

        filename_pos++;
        read_block(nextdir_block_id);
        cur_dir = cached_block_base;
    }

    disable_sum();
    /* Search Parent Dir End */

    uint16_t inode_id;
    int type;

    read_block(lastdir_block);
    cur_dir = cached_block_base;
    for(int i = 0; i < 128; i++){
        if(cur_dir->entry[i].type != EMPTY && !strcmp(cur_dir->entry[i].name, nextdirname)){
            inode_id = cur_dir->entry[i].inode;
            type = cur_dir->entry[i].type;
            break;
        }
    }

    enable_sum();
    if(mode == 0){
        if(type == DIR){
            disable_sum();
            return 0;
        }

        inode_t* inode = read_inode(inode_id);
        inode->link = inode->link + 1;
        write_inode(inode_id);

        read_block(current_dir_block);
        cur_dir = cached_block_base;
        for(int i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, newfile)){
                disable_sum();
                return 0;
            }
        }
        for(int i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == EMPTY){
                cur_dir->entry[i].type = FILE;
                strcpy(cur_dir->entry[i].name, newfile);
                cur_dir->entry[i].inode = inode_id;
                write_block(current_dir_block);
                disable_sum();
                return 1;
            }
        }
    }
    else if(mode == 1){
        read_block(current_dir_block);
        cur_dir = cached_block_base;
        for(int i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == FILE && !strcmp(cur_dir->entry[i].name, newfile)){
                disable_sum();
                return 0;
            }
        }
        for(int i = 0; i < 128; i++){
            if(cur_dir->entry[i].type == EMPTY){
                uint16_t new_inode_id = alloc_inode();
                cur_dir->entry[i].type = type;
                strcpy(cur_dir->entry[i].name, newfile);
                cur_dir->entry[i].inode = new_inode_id;
                write_block(current_dir_block);

                inode_t* inode = read_inode(inode_id);
                uint32_t direct[10];
                uint32_t indirect[2];
                uint64_t size;
                uint32_t link;
                for(int j = 0; j < 10; j++){
                    direct[i] = inode->direct_blocks[i];
                }
                indirect[0] = inode->indirect_blocks[0];
                indirect[1] = inode->indirect_blocks[1];
                size = inode->size;
                link = inode->link;

                inode = read_inode(new_inode_id);
                inode->mode = 1;
                inode->owner = current_running[cpu_id]->pid;
                inode->size = size;
                inode->link = link;
                for(int j = 0; j < 10; j++){
                    inode->direct_blocks[i] = direct[i];
                }
                inode->indirect_blocks[0] = indirect[0];
                inode->indirect_blocks[1] = indirect[1];
                write_inode(new_inode_id);

                return 1;
            }
        }
    }
}

#include <stdatomic.h>
#include <stdint.h>
#include <mthread.h>
#include <assert.h>
#include <sys/syscall.h>

void mthread_barrier_init(mthread_barrier_t * barrier, unsigned count)
{
    barrier->count = count;
    atomic_exchange(&barrier->reached, 0);
    barrier->binsem_id = sys_binsem_get((int)barrier);
}
void mthread_barrier_wait(mthread_barrier_t *barrier)
{
    sys_binsem_op(barrier->binsem_id, BINSEM_OP_LOCK);
    fetch_add(&barrier->reached, 1);
    if((barrier->reached) == (barrier->count)){
        atomic_exchange(&barrier->reached, 0);
        sys_binsem_op(barrier->binsem_id, BINSEM_OP_UNLOCK);
        sys_futex_wakeup((unsigned long*)barrier, barrier->count);                    
    }
    else{
        sys_binsem_op(barrier->binsem_id, BINSEM_OP_UNLOCK);      
        sys_futex_wait((unsigned long*)barrier);
    }
}
void mthread_barrier_destroy(mthread_barrier_t *barrier)
{
    barrier->count = -1;
    barrier->reached = -1;
}

int mthread_cond_init(mthread_cond_t *cond)
{
    atomic_exchange(cond, 0);
    return 1;
}
int mthread_cond_destroy(mthread_cond_t *cond) 
{
    sys_futex_wakeup((unsigned long*)cond, *cond);
    atomic_exchange(cond, -1);
    return 1;
}
int mthread_cond_wait(mthread_cond_t *cond, int binsem_id)
{
    fetch_add(cond, 1);
    sys_binsem_op(binsem_id, BINSEM_OP_UNLOCK);
    sys_futex_wait((unsigned long*)cond);
    sys_binsem_op(binsem_id, BINSEM_OP_LOCK);
    return 1;
}
int mthread_cond_signal(mthread_cond_t *cond)
{
    sys_futex_wakeup((unsigned long*)cond, 1);
    fetch_sub(cond, 1);
    return 1;
}
int mthread_cond_broadcast(mthread_cond_t *cond)
{
    sys_futex_wakeup((unsigned long*)cond, *cond);
    atomic_exchange(cond, 0);
    return 1;
}

int mthread_semaphore_init(mthread_semaphore_t *sem, int val)
{
    atomic_exchange(&sem->value, val);
    sem->binsem_id = sys_binsem_get((int)sem);
    return 1;
}
int mthread_semaphore_up(mthread_semaphore_t *sem)
{
    sys_binsem_op(sem->binsem_id, BINSEM_OP_LOCK);
    fetch_add(&sem->value, 1);
    sys_binsem_op(sem->binsem_id, BINSEM_OP_UNLOCK);
    sys_futex_wakeup((unsigned long *)&sem->value, 1);
    return 1;
}
int mthread_semaphore_down(mthread_semaphore_t *sem)
{
    sys_binsem_op(sem->binsem_id, BINSEM_OP_LOCK);
    while (sem->value <= 0) {
        sys_binsem_op(sem->binsem_id, BINSEM_OP_UNLOCK);
        sys_futex_wait((unsigned long *)&sem->value);
        sys_binsem_op(sem->binsem_id, BINSEM_OP_LOCK);
    }
    fetch_sub(&sem->value, 1);
    sys_binsem_op(sem->binsem_id, BINSEM_OP_UNLOCK);
    return 1;
}
int mthread_semaphore_destroy(mthread_semaphore_t *sem)
{
    sys_futex_wakeup((unsigned long *)&sem->value, sem->value);
    atomic_exchange(&sem->value, -1);
    return 1;
}

