#ifndef INCLUDE_LIST_H_
#define INCLUDE_LIST_H_

#include <type.h>

// double-linked list
typedef struct list_node
{
    struct list_node *next, *prev;
} list_node_t;

typedef list_node_t list_head;

#define offsetof(TYPE, MEMBER) ((size_t) &((TYPE *)0)->MEMBER)
#define list_entry(ptr, type, member)                    \
    ({                                                     \
        const typeof(((type *)0)->member) *__mptr = (ptr); \
        (type *)((char *)__mptr - offsetof(type, member)); \
    })

// LIST_HEAD is used to define the head of a list.
#define LIST_HEAD(name) struct list_node name = {&(name), &(name)}

static inline void init_list_head(list_head *list)
{
    list->next = list;
    list->prev = list;
}

static inline void _list_add(
    list_node_t *node, list_node_t *prev, list_node_t *next)
{
    next->prev = node;
    node->next = next;
    node->prev = prev;
    prev->next = node;
}

static inline void _list_del(list_node_t *prev, list_node_t *next)
{
    next->prev = prev;
    prev->next = next;
}
static inline void list_del(list_node_t *entry)
{
    if (entry->prev != NULL && entry->next != NULL) {
        _list_del(entry->prev, entry->next);
        entry->prev = NULL;
        entry->next = NULL;
    }
}

static inline void list_add(list_node_t *node, list_node_t *head)
{
    _list_add(node, head, head->next);
}

static inline void list_add_tail(
    list_node_t *node, list_node_t *head)
{
    _list_add(node, head->prev, head);
}

static inline void list_move(list_node_t *node, list_head *head)
{
    list_del(node);
    list_add(node, head);
}

static inline int list_empty(const list_head *head)
{
    return head->next == head;
}

#endif

#include <os/futex.h>
#include <os/irq.h>
#include <os/mm.h>
#include <assert.h>
#include <os/smp.h>
#include <os/binsem.h>
#include <pgtable.h>

futex_bucket_t futex_buckets[FUTEX_BUCKETS];

void init_system_futex()
{
    for (int i = 0; i < FUTEX_BUCKETS; ++i) {
        init_list_head(&futex_buckets[i]);
    }
}

// a simple hash function
static int futex_hash(uint64_t x)
{
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
    x = x ^ (x >> 31);
    return x % FUTEX_BUCKETS;
}

static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
{
    int key = futex_hash((uint64_t)val_addr);
    list_node_t *head = &futex_buckets[key];
    for (list_node_t *p = head->next; p != head; p = p->next) {
        futex_node_t *node = list_entry(p, futex_node_t, list);
        if (node->futex_key == (uint64_t)val_addr) {
            return node;
        }
    }

    if (create) {
        futex_node_t *node = (futex_node_t*)pa2kva((uintptr_t)kmalloc(sizeof(futex_node_t)));
        node->futex_key = (uint64_t)val_addr;
        init_list_head(&node->block_queue);
        list_add_tail(&node->list, &futex_buckets[key]);
        return node;
    }

    return NULL;
}

void futex_wait(volatile uint64_t *val_addr, int binsem_id)
{
    disable_preempt();

    futex_node_t *node = get_node(val_addr, 1);
    assert(node != NULL);
    do_block(&current_running[cpu_id]->list, &node->block_queue);
    binsem_op(binsem_id, BINSEM_OP_UNLOCK);
    scheduler(); 

    enable_preempt();
}

void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
{
    disable_preempt();
    futex_node_t *node = get_node(val_addr, 0);

    if (node != NULL) {
        for (int i = 0; i < num_wakeup; ++i) {
            if (list_empty(&node->block_queue)) break;

            do_unblock(node->block_queue.next);
        }
    }

    scheduler();
    enable_preempt();
}

