#ifndef DISK_H
#define DISK_H

#include <type.h>

/* * * * * * * * * * * * * * * * * * * * * * * 
Disk Layout
    0 -     2,047 (    2,048): Kernel Image
2,048 -     4,095 (    2,048): Swap

4,096 -     4,096 (        1): Super Block
4,097 -     4,160 (       64): Block Map
4,161 -     4,161 (        1): Inode Map
4,162 -     4,673 (      512): Inode
5,120 - 2,102,271 (2,097,152): Block
* * * * * * * * * * * * * * * * * * * * * * */

#define SUPERBLOCK_ID      4096
#define BLOCKMAP_BEGIN_ID  4097
#define INODEMAP_ID        4161
#define INODE_BEGIN_ID     4162
#define BLOCK_BEGIN_ID     5120

extern void read_superblock();
extern void write_superblock();
extern void read_blockmap();
extern void write_blockmap();
extern void read_inodemap();
extern void write_inodemap();
extern uintptr_t read_inode(uint16_t inode_id);
extern void write_inode(uint16_t inode_id);
extern void read_block(uint32_t block_id);
extern void write_block(uint32_t block_id);

extern uint16_t alloc_inode();
extern uint32_t alloc_block();
extern void free_inode(uint16_t inode_id);
extern void free_block(uint32_t block_id);

#endif /* DISK_H */

#include <os/fs.h>
#include <os/disk.h>
#include <sbi.h>
#include <pgtable.h>

void read_superblock()
{
    sbi_sd_read(kva2pa(SUPERBLOCK_CACHE), 1, SUPERBLOCK_ID);
}

void write_superblock()
{
    sbi_sd_write(kva2pa(SUPERBLOCK_CACHE), 1, SUPERBLOCK_ID);
}

void read_blockmap()
{
    sbi_sd_read(kva2pa(BLOCKMAP_CACHE), 64, BLOCKMAP_BEGIN_ID);
}

void write_blockmap()
{
    sbi_sd_write(kva2pa(BLOCKMAP_CACHE), 64, BLOCKMAP_BEGIN_ID);
}

void read_inodemap()
{
    sbi_sd_read(kva2pa(INODEMAP_CACHE), 1, INODEMAP_ID);
}

void write_inodemap()
{
    sbi_sd_write(kva2pa(INODEMAP_CACHE), 1, INODEMAP_ID);
}

uintptr_t read_inode(uint16_t inode_id)
{
    uint64_t sd_block_id = INODE_BEGIN_ID + inode_id / 8;
    sbi_sd_read(kva2pa(INODE_CACHE), 1, sd_block_id);
    cached_inode_id = inode_id;
    uintptr_t ret = INODE_CACHE + 64 * (inode_id % 8);
    return ret;
}

void write_inode(uint16_t inode_id)
{
    uint64_t sd_block_id = INODE_BEGIN_ID + inode_id / 8;
    sbi_sd_write(kva2pa(INODE_CACHE), 1, sd_block_id);
}

void read_block(uint32_t block_id)
{
    uint64_t sd_block_id = BLOCK_BEGIN_ID + block_id * 8;
    sbi_sd_read(kva2pa(BLOCK_CACHE), 8, sd_block_id);
    cached_block_id = block_id;
}

void write_block(uint32_t block_id)
{
    uint64_t sd_block_id = BLOCK_BEGIN_ID + block_id * 8;
    sbi_sd_write(kva2pa(BLOCK_CACHE), 8, sd_block_id);
}

// Returns inode id
uint16_t alloc_inode()
{
    read_inodemap();
    uint8_t *bitmap = (uint8_t *)inodemap;
    for (uint32_t byte_idx = 0; byte_idx < 512; byte_idx++) {
        if (bitmap[byte_idx] == 0xff) {
            continue;
        }
        for (uint32_t bit = 0; bit < 8; bit++) {
            uint8_t mask = 1u << bit;
            if ((bitmap[byte_idx] & mask) == 0) {
                bitmap[byte_idx] |= mask;
                write_inodemap();
                read_superblock();
                superblock->used_inode_num++;
                write_superblock();
                return (uint16_t)(byte_idx * 8 + bit);
            }
        }
    }

    return 0xffff;
}

// Returns block id
uint32_t alloc_block()
{
    read_blockmap();
    uint8_t *bitmap = (uint8_t *)blockmap;
    for (uint32_t byte_idx = 0; byte_idx < 64 * 512; byte_idx++) {
        if (bitmap[byte_idx] == 0xff) {
            continue;
        }
        for (uint32_t bit = 0; bit < 8; bit++) {
            uint8_t mask = 1u << bit;
            if ((bitmap[byte_idx] & mask) == 0) {
                bitmap[byte_idx] |= mask;
                write_blockmap();
                read_superblock();
                superblock->used_block_num++;
                write_superblock();
                return byte_idx * 8 + bit;
            }
        }
    }

    return 0xffffffff;
}

void free_inode(uint16_t inode_id)
{
    read_inodemap();
    uint32_t byte_idx = inode_id / 8;
    uint8_t mask = 1u << (inode_id % 8);
    uint8_t *bitmap = (uint8_t *)inodemap;

    if (bitmap[byte_idx] & mask) {
        bitmap[byte_idx] &= (uint8_t)~mask;
        write_inodemap();
        read_superblock();
        if (superblock->used_inode_num > 0) {
            superblock->used_inode_num--;
        }
        write_superblock();
    }
}

void free_block(uint32_t block_id)
{
    read_blockmap();
    uint32_t byte_idx = block_id / 8;
    uint8_t mask = 1u << (block_id % 8);
    uint8_t *bitmap = (uint8_t *)blockmap;

    if (bitmap[byte_idx] & mask) {
        bitmap[byte_idx] &= (uint8_t)~mask;
        write_blockmap();
        read_superblock();
        if (superblock->used_block_num > 0) {
            superblock->used_block_num--;
        }
        write_superblock();
    }
}
